const mongoose = require('mongoose');
const { buildSubgraphSchema } = require('@apollo/subgraph');
const { GraphQLError } = require('graphql');
const gql = require('graphql-tag');
const PolicyModel = require('../models/DocumentPolicy');

const typeDefs = gql`
  type Mutation {
    updateDocumentAccessPolicy(policyId: ID!, isPublic: Boolean!, allowedDomain: String): DocumentPolicyPayload!
  }

  type DocumentPolicyPayload {
    policyId: ID!
    isPublic: Boolean!
    allowedDomain: String
  }
`;

const resolvers = {
  Mutation: {
    updateDocumentAccessPolicy: async (_, { policyId, isPublic, allowedDomain }, context) => {
      if (!context.user) {
        throw new GraphQLError('Authentication required', { extensions: { code: 'UNAUTHENTICATED' } });
      }
      const existing = await PolicyModel.findById(policyId);
      if (!existing || existing.ownerUserId !== context.user.id) {
        throw new GraphQLError('Access denied to update document policy', { extensions: { code: 'FORBIDDEN' } });
      }
      const policy = await PolicyModel.findByIdAndUpdate(
        policyId,
        { isPublic, allowedDomain, updatedAt: new Date() },
        { new: true }
      );
      return { policyId: policy._id, isPublic: policy.isPublic, allowedDomain: policy.allowedDomain };
    }
  }
};
